"""Generate a value sequence and count it into a histogram, both on the GPU."""

import sys

import numpy as np
import wgpu

WORKGROUP_SIZE = 256
MAX_WORKGROUPS = 4096
MAX_BINS = 256

SHADER = """
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, 256>;

var<workgroup> local_hist: array<atomic<u32>, 256>;

fn value_at(i: u32) -> u32 {
    let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
    let b = (a * a + a * 37u + 11u) % 40009u;
    let c = (b * 613u + 7919u) % 40009u;
    let d = (c + (i / 40000u) * 7919u) % 40009u;
    return d % 1000u;
}

@compute @workgroup_size(256)
fn main(
    @builtin(local_invocation_index) lid: u32,
    @builtin(workgroup_id) wid: vec3<u32>,
    @builtin(num_workgroups) nwg: vec3<u32>,
) {
    atomicStore(&local_hist[lid], 0u);
    workgroupBarrier();

    let stride = nwg.x * 256u;
    for (var i = wid.x * 256u + lid; i < params.count; i = i + stride) {
        let bin = value_at(i) * params.bins / 1000u;
        atomicAdd(&local_hist[bin], 1u);
    }
    workgroupBarrier();

    if (lid < params.bins) {
        let n = atomicLoad(&local_hist[lid]);
        if (n != 0u) {
            atomicAdd(&hist[lid], n);
        }
    }
}
"""


def parse_input(path):
    with open(path) as f:
        fields = f.read().split()
    if len(fields) != 3:
        raise ValueError("expected '<count> <seed> <bins>'")
    count, seed, bins = (int(x) for x in fields)
    if not (0 <= count <= 4_000_000 and 0 <= seed <= 9999 and 1 <= bins <= MAX_BINS):
        raise ValueError("input out of range")
    return count, seed, bins


def gpu_histogram(count, seed, bins):
    device = wgpu.utils.get_default_device()

    params = np.array([count, seed, bins, 0], dtype=np.uint32)
    params_buf = device.create_buffer_with_data(
        data=params, usage=wgpu.BufferUsage.UNIFORM
    )
    hist_buf = device.create_buffer_with_data(
        data=np.zeros(MAX_BINS, dtype=np.uint32),
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf}},
            {"binding": 1, "resource": {"buffer": hist_buf}},
        ],
    )

    workgroups = max(1, min(MAX_WORKGROUPS, -(-count // WORKGROUP_SIZE)))
    encoder = device.create_command_encoder()
    compute = encoder.begin_compute_pass()
    compute.set_pipeline(pipeline)
    compute.set_bind_group(0, bind_group)
    compute.dispatch_workgroups(workgroups, 1, 1)
    compute.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(hist_buf)
    return np.frombuffer(data, dtype=np.uint32)[:bins].tolist()


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    count, seed, bins = parse_input(argv[1])
    counts = gpu_histogram(count, seed, bins)
    out = [f"BIN {i} {n}" for i, n in enumerate(counts)]
    out.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(out) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

